code='''from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            yield color, cells


def _shape(cells):
    mr = min(r for r, c in cells)
    mc = min(c for r, c in cells)
    return frozenset((r-mr, c-mc) for r, c in cells)


def transform(grid):
    out = [row[:] for row in grid]
    components = list(_components(grid))
    colors_by_shape = {}
    for color, cells in components:
        if color != 1:
            colors_by_shape.setdefault(_shape(cells), set()).add(color)
    for color, cells in components:
        if color == 1:
            matches = colors_by_shape.get(_shape(cells), set())
            if len(matches) == 1:
                replacement = next(iter(matches))
                for r, c in cells:
                    out[r][c] = replacement
    return out
'''
